function renderProjectPanel(){$('assetPanel').innerHTML=`<div class="project-options"><p>项目文件会嵌入你导入的图片和音频、校准值、外观与编队设置，也可包含当前战局。随包的 ${Object.values(D.slots).filter(s=>s.src).length} 张默认 PNG 仍从 assets 文件夹读取，不重复嵌入。</p><p class="muted">离线版请保持整个文件夹一起移动。网页与离线版的本地存储相互独立，换浏览器/换设备后导入项目 JSON 即可恢复自定义素材；默认图需要这套程序的同版素材。</p><label class="inline-check"><input type="checkbox" id="includeBattle" checked>导出时包含当前战局</label><div class="project-buttons"><button id="exportProject" class="primary">导出可携项目 JSON</button><label class="file-label">导入项目<input id="importProject" type="file" accept="application/json,.json"></label></div><label class="inline-check"><input type="checkbox" id="reduceMotion" ${project.settings.reducedMotion?'checked':''}>减少动作与闪烁</label><p class="muted">本地状态：${store.available?'IndexedDB 可用；素材刷新后仍保存。':'当前浏览器不允许持久缓存，请及时导出项目。'} 不发送素材、战局或日志到服务器。</p><div class="rules-note">导入为原子操作：格式、大小、资源类型与战局全部通过检查后才替换当前项目。失败时保持当前项目与战局。不会执行 JSON 中的脚本、SVG、远程图片地址或网页。</div><div class="project-buttons"><button id="clearCache" class="danger">清理本程序本地缓存</button><button id="resetAllAssets">恢复所有默认素材 / 校准</button></div><p class="asset-description">清理仅影响此程序的本地数据库；不会删除你电脑上的原始文件。请先导出想保留的项目。</p></div>`;$('exportProject').onclick=()=>safeAction(()=>exportProject($('includeBattle').checked));$('importProject').onchange=e=>safeAction(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>140*1024*1024)throw new Error('项目文件超过 140 MiB');const parsed=JSON.parse(await f.text());const checked=await validateProject(parsed);pause();epoch++;project=checked.project;if(checked.battle){battle=checked.battle;project.battleConfig=clone(battle.options);busy=false;auto=false;visuals.clear();floats=[];stageEffects=[];resetMenu();render();}else startBattle(project.battleConfig);stopAllAudio();imageCache.clear();renderCache.clear();await persistProject();await saveBattle(true);renderProjectPanel();$('sceneLabel').textContent=project.background.data?'本地背景 · '+project.background.name:'中性调试舞台 · 等待背景素材';status(checked.migration||'项目导入成功。自定义素材已嵌入，无需重新选择原文件。');if(checked.migration)showMigration(checked.migration);});$('reduceMotion').onchange=e=>{project.settings.reducedMotion=e.target.checked;queueProjectSave();};$('clearCache').onclick=()=>{if(!window.confirm('清除本程序保存的战局、素材和设置？电脑原文件不会被删除。'))return;safeAction(async()=>{await store.clear();savedSnapshot=null;project=freshProject();stopAllAudio();startBattle(project.battleConfig,false);clearTimeout(saveTimer);await store.clear();$('saveStatus').textContent='已清理本地缓存；当前为默认临时战局';renderProjectPanel();status('本程序本地缓存已清理。后续新设置会再次保存。');});};$('resetAllAssets').onclick=()=>{if(!window.confirm('恢复所有随包素材与校准？当前战局不变，导入素材将从此项目移除。'))return;const base=freshProject();project.overrides={};project.calibration={};project.appearance={};project.background=base.background;project.audio={};$('sceneLabel').textContent='中性调试舞台 · 等待背景素材';imageCache.clear();renderCache.clear();stopAllAudio();queueProjectSave();renderProjectPanel();status('已恢复全部默认素材。');};}
async function dataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('无法读取文件'));r.readAsDataURL(file);});}
async function readImage(file){if(file.size>20*1024*1024)throw new Error('图片超过 20 MiB');const bytes=new Uint8Array(await file.slice(0,16).arrayBuffer());let mime='';if(bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71)mime='image/png';else if(bytes[0]===255&&bytes[1]===216)mime='image/jpeg';else if(String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP')mime='image/webp';else if(String.fromCharCode(...bytes.slice(0,3))==='GIF')mime='image/gif';else throw new Error('只接受可识别的 PNG、JPG、WebP、GIF，不接受 SVG');const data=await dataURL(new Blob([file],{type:mime}));const dims=await decodeImage(data);return {data,name:file.name.slice(0,180),mime,width:dims.width,height:dims.height};}
async function decodeImage(data){return new Promise((resolve,reject)=>{const im=new Image(),timer=setTimeout(()=>reject(new Error('图片解码超时')),12000);im.onload=()=>{clearTimeout(timer);if(im.width>10000||im.height>10000||im.width*im.height>50000000)return reject(new Error('图片尺寸过大，最长边 ≤10000、总像素 ≤5000万'));resolve({width:im.width,height:im.height});};im.onerror=()=>{clearTimeout(timer);reject(new Error('图片损坏或格式不支持'));};im.src=data;});}
async function readAudio(file){if(file.size>30*1024*1024)throw new Error('音频超过 30 MiB');const b=new Uint8Array(await file.slice(0,16).arrayBuffer()),head=String.fromCharCode(...b);let mime='';if(head.startsWith('RIFF')&&head.slice(8,12)==='WAVE')mime='audio/wav';else if(head.startsWith('OggS'))mime='audio/ogg';else if(head.startsWith('ID3')||(b[0]===255&&(b[1]&224)===224))mime='audio/mpeg';else if(head.slice(4,8)==='ftyp')mime='audio/mp4';else if(b[0]===26&&b[1]===69&&b[2]===223&&b[3]===163)mime='audio/webm';else throw new Error('音频文件头不受支持，请使用 WAV、MP3、OGG、M4A');return {data:await dataURL(new Blob([file],{type:mime})),name:file.name.slice(0,180),mime};}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportProject(include){const data={...clone(project),battle:include&&battle?battle.snapshot():null,exportedAt:new Date().toISOString(),instructions:'Imported images/audio embedded. Built-in sprites depend on the matching assets directory.'};download('遭遇演算_项目_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(data));status('项目已导出；包含自定义素材'+(include?'及当前战局':'')+'。');}
function isPlain(x){return !!x&&typeof x==='object'&&!Array.isArray(x)&&Object.getPrototypeOf(x)===Object.prototype;}
function bounded(v,lo,hi){return typeof v==='number'&&Number.isFinite(v)&&v>=lo&&v<=hi;}
function assertPlain(x,name){if(!isPlain(x))throw new Error(name+'格式无效');for(const k of Object.keys(x))if(['__proto__','constructor','prototype'].includes(k))throw new Error('不允许的字段 '+k);}
async function validateProject(raw){assertPlain(raw,'项目');if(raw.schema!=='resonant-project-v1'||raw.version!==1||raw.assetSet!=='20261009-v1')throw new Error('项目版本不匹配');const p=freshProject();let bytes=0;for(const k of ['overrides','calibration','appearance','background','audio','settings','battleConfig'])assertPlain(raw[k],k);
 for(const [key,item] of Object.entries(raw.overrides)){if(!own(D.slots,key))throw new Error('未知素材槽 '+key);p.overrides[key]=await checkedMedia(item,'image');bytes+=p.overrides[key].data.length;}
 for(const [key,cal] of Object.entries(raw.calibration)){if(!own(D.slots,key))throw new Error('未知校准槽');assertPlain(cal,'校准');const ranges={scale:[.1,4],x:[-500,500],y:[-500,500],ground:[-200,300],bodyHeight:[20,3000],outline:[0,3],anchorX:[-1,2],anchorY:[-1,2],headX:[0,1],headY:[0,1],weaponX:[0,1],weaponY:[0,1],portraitX:[0,1],portraitY:[0,1],portraitW:[.01,1],portraitH:[.01,1]};const c={};for(const [k,v] of Object.entries(cal)){if(!own(ranges,k)||!bounded(v,...ranges[k]))throw new Error('校准参数超范围：'+k);c[k]=v;}p.calibration[key]=c;}
 for(const [key,value] of Object.entries(raw.appearance)){if(!own(P.characters,key)||!(own(D.forms[key]||{},value)||key==='rover'&&['male_default','male_school','female_default','female_school'].includes(value)))throw new Error('外观无效');p.appearance[key]=value;}
 const bg=raw.background;if(bg.data){const item=await checkedMedia(bg,'image');p.background={...p.background,...item};bytes+=item.data.length;}if(!['cover','contain'].includes(bg.fit)||!bounded(bg.opacity,0,1))throw new Error('背景参数无效');p.background.fit=bg.fit;p.background.opacity=bg.opacity;
 for(const [key,item] of Object.entries(raw.audio)){if(!own(AUDIO,key))throw new Error('音频事件未知');p.audio[key]=await checkedMedia(item,'audio');bytes+=p.audio[key].data.length;}
 if(bytes>130*1024*1024)throw new Error('嵌入素材总量过大');for(const k of ['master','sfx','bgm']){if(!bounded(raw.settings[k],0,1))throw new Error('音量无效');p.settings[k]=raw.settings[k];}if(!bounded(raw.settings.outline,0,3))throw new Error('描边无效');p.settings.outline=raw.settings.outline;for(const k of ['showAnchors','reducedMotion']){if(typeof raw.settings[k]!=='boolean')throw new Error('设置无效');p.settings[k]=raw.settings[k];}
 const test=new BattleEngine(P,raw.battleConfig);p.battleConfig=clone(test.options);let loaded=null,migration='';if(raw.battle){if(raw.battle.parameter_version!==P.schema_version){if(['0.1.2-candidate','0.2.0-candidate'].includes(raw.battle.parameter_version)&&raw.battle.schema==='battle-engine-v1')migration='旧版 '+raw.battle.parameter_version+' 战局与当前 '+P.schema_version+' AP规则不兼容。已保留素材、外观、校准和编队；旧战局不续接，按当前规则重新开场。';else throw new Error('战局参数版本不支持');}else loaded=BattleEngine.restore(P,raw.battle);}return {project:p,battle:loaded,migration};}
async function checkedMedia(item,kind){assertPlain(item,'素材');if(typeof item.name!=='string'||item.name.length>180||typeof item.data!=='string')throw new Error('素材字段无效');const re=kind==='image'?/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/]*={0,2}$/:/^data:audio\/(wav|mpeg|ogg|mp4|webm);base64,[A-Za-z0-9+/]*={0,2}$/;if(!re.test(item.data)||item.data.length>(kind==='image'?28:42)*1024*1024)throw new Error('素材类型或大小不受支持');const comma=item.data.indexOf(','),mime=item.data.slice(5,comma-7),base64=item.data.slice(comma+1);let binary;try{binary=atob(base64);}catch{throw new Error('素材编码损坏');}const blob=new Blob([Uint8Array.from(binary,c=>c.charCodeAt(0))],{type:mime});const file=new File([blob],item.name,{type:mime});return kind==='image'?readImage(file):readAudio(file);}
