 const cost=Object.entries(s.cost||{}).map(([k,v])=>(LABEL[k]||k)+' '+v).join(' / ')||'无',gain=Object.entries(s.gain||{}).map(([k,v])=>(LABEL[k]||k)+' +'+v).join(' / ')||'无';
 const target=s.targetText||(s.aoe?'全部敌方':({self:'自己',ally:'一名队友',other_ally:'另一名队友',all_allies:'全体队友'})[s.target]||'一名敌人');
